const fs = require("fs");
const path = require("path");
// @cloudflare/codemode is an optional peer of agents/browser that this check does not use.
// node_modules is read-only, so resolve the bare specifier to a stub in /w with a module hook instead of writing into node_modules.
const codemodeStub = "/w/codemode-stub.mjs";
fs.writeFileSync(codemodeStub, "export class CodemodeConnector {}\nexport class CodemodeRuntime {}\n");
const codemodeUrl = require("url").pathToFileURL(codemodeStub).href;
require("module").registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier === "@cloudflare/codemode") return { url: codemodeUrl, format: "module", shortCircuit: true };
    return nextResolve(specifier, context);
  }
});
fs.writeFileSync("/w/check.mjs", "export default await import('agents/browser');\n");
import("/w/check.mjs").then((m) => {
  const mod = m.default;
  const version = JSON.parse(fs.readFileSync("/w/node_modules/agents/package.json", "utf8")).version;
  if (typeof mod.CdpSession !== "function") {
    console.error("ERROR: agents/browser does not export a CdpSession class");
    process.exit(2);
  }
  if (mod.CdpConnection === undefined) {
    console.error("FAIL: agents/browser exports no CdpConnection; CdpSession is the only name (agents " + version + ")");
    process.exit(1);
  }
  if (mod.CdpConnection !== mod.CdpSession) {
    console.error("ERROR: CdpSession is not an alias of CdpConnection");
    process.exit(2);
  }
  console.log("OK: agents " + version + " CdpSession === CdpConnection");
  process.exit(0);
}).catch((e) => {
  console.error("ERROR: import failed: " + (e && e.message));
  process.exit(2);
});

